// The practical processes from Robert Allen Bartlett, "Real Alchemy: A Primer of Practical Alchemy"
// (Quinquangle Press, 2006), rewritten in plain English. Each process says what it is, what the book
// says it helps with, what you need, and every step with its reason. Claims and warnings are the book's.

export type Tier = 'easy' | 'skill' | 'danger';
export type GroupK = 'plants' | 'basics' | 'waters' | 'metals' | 'antimony' | 'stone';
export type Tone = 'nigredo' | 'albedo' | 'citrin' | 'rubedo';

export interface Step { do: string; why: string }
export interface Process {
  id: string; group: GroupK; title: string; aka?: string;
  short: string;          // one line for the list
  what: string;           // what it is
  helps: string;          // what it helps with, as the book says
  need?: string[];
  time?: string;
  tier: Tier;
  steps: Step[];
  use?: string;           // how the book says to take it
  care?: string[];        // the book's own warnings
  note?: string;          // anything else the book adds
  extra?: 'oils' | 'week' | 'fractions';
}

export const TIERS: Record<Tier, { label: string; icon: string; long: string }> = {
  easy: { label: 'Beginner', icon: '✓', long: 'The book counts this among the works anyone can do with household things.' },
  skill: { label: 'Needs practice', icon: '!', long: 'Needs a still, steady heat and some practice.' },
  danger: { label: 'Dangerous', icon: '✕', long: 'The book warns that mineral works are deadly without real skill and care. Learn the theory first.' },
};

